reference_solution:
def count_pairs_below_target(nums,target):
    values=sorted(nums);left=0;right=len(values)-1;answer=0
    while left<right:
        if values[left]+values[right]<target:
            answer+=right-left;left+=1
        else:right-=1
    return answer

